const commander = require('../');

describe('subcommand name and alias clashes', () => {
  test('when .command() repeats name then throw', () => {
    const program = new commander.Command();
    program.command('sub');
    expect(() => program.command('sub')).toThrow('cannot add command');
  });

  test('when .command() name matches alias then throw', () => {
    const program = new commander.Command();
    program.command('sub').alias('s');
    expect(() => program.command('s')).toThrow('cannot add command');
  });

  test('when .addCommand() repeats name then throw', () => {
    const program = new commander.Command();
    program.addCommand(new commander.Command('sub'));
    expect(() => program.addCommand(new commander.Command('sub'))).toThrow('cannot add command');
  });

  test('when .addCommand() alias matches name then throw', () => {
    const program = new commander.Command();
    program.command('sub');
    expect(() => program.addCommand(new commander.Command('other').alias('sub'))).toThrow('cannot add command');
  });

  test('when .alias() matches other command name then throw', () => {
    const program = new commander.Command();
    program.command('a');
    const b = program.command('b');
    expect(() => b.alias('a')).toThrow('cannot add alias');
  });

  test('when .alias() matches other command alias then throw', () => {
    const program = new commander.Command();
    program.command('a').alias('x');
    const b = program.command('b');
    expect(() => b.alias('x')).toThrow('cannot add alias');
  });

